BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Cardiac Tamponade' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Cardiac Tamponade', 'Beck''s triad, diagnosis, and emergency management', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - Cardiac Tamponade (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'Cardiac Tamponade - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Definition" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Definition" is most accurate?', '[{"id": "a", "text": "Treat as an emergency because rapid deterioration and arrest can occur."}, {"id": "b", "text": "Tamponade is a benign condition that can always wait for routine follow-up."}, {"id": "c", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "d", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}]'::jsonb, '["a"]'::jsonb, 'Correct because Cardiac tamponade is fluid accumulation in the pericardial sac that compresses the heart. Treat as an emergency because rapid deterioration and arrest can occur.', 'Cardiac Tamponade - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hemodynamic mechanism" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Hemodynamic mechanism" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Tamponade increases preload by compressing the ventricles."}, {"id": "b", "text": "A 2 mmHg inspiratory change defines pulsus paradoxus."}, {"id": "c", "text": "Rising intrapericardial pressure limits chamber filling."}, {"id": "d", "text": "Tamponade is primarily distributive shock from vasodilation."}]'::jsonb, '["c"]'::jsonb, 'Correct because Increased intrapericardial pressure compresses all four chambers and causes obstructive shock. Recognize obstructive shock pattern when hypotension and poor perfusion progress.', 'Cardiac Tamponade - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Acute volume threshold" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Acute volume threshold" in Cardiac Tamponade?', '[{"id": "a", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "b", "text": "Volume rate of accumulation is irrelevant in tamponade risk."}, {"id": "c", "text": "Do not underestimate small but rapidly accumulating effusions."}, {"id": "d", "text": "Only massive chronic effusions can cause tamponade."}]'::jsonb, '["c"]'::jsonb, 'Correct because As little as 150–200 mL acutely accumulated fluid can cause tamponade. Do not underestimate small but rapidly accumulating effusions.', 'Cardiac Tamponade - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Cause profile" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Cause profile" in Cardiac Tamponade?', '[{"id": "a", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "b", "text": "Increased urine output is expected in tamponade shock."}, {"id": "c", "text": "Penetrating or blunt trauma can precipitate tamponade."}, {"id": "d", "text": "Aortic dissection is excluded as a tamponade cause."}]'::jsonb, '["c"]'::jsonb, 'Correct because Pericarditis is the most common cause, with trauma, post-op bleeding, malignancy, and aortic dissection also listed. Screen etiology rapidly while preparing definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Additional causes" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Additional causes" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Tamponade causes are limited to congenital defects."}, {"id": "b", "text": "Radiation therapy cannot contribute to tamponade."}, {"id": "c", "text": "Tamponade typically causes widened pulse pressure."}, {"id": "d", "text": "Autoimmune disease and uremia are included causes."}]'::jsonb, '["d"]'::jsonb, 'Correct because Additional causes include MI free-wall rupture, iatrogenic catheterization complications, SLE, uremia, and radiation therapy. Integrate procedural and systemic risk factors into rapid triage.', 'Cardiac Tamponade - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Beck triad" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Beck triad" is most accurate?', '[{"id": "a", "text": "Pulsus paradoxus is defined as a diastolic rise."}, {"id": "b", "text": "Wheezing replaces JVD in Beck triad."}, {"id": "c", "text": "Muffled heart sounds are part of Beck triad."}, {"id": "d", "text": "Electrical alternans is a benign normal variant."}]'::jsonb, '["c"]'::jsonb, 'Correct because Beck triad consists of muffled heart sounds, JVD, and hypotension. Escalate immediately when triad features cluster together.', 'Cardiac Tamponade - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Muffled heart sounds meaning" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Muffled heart sounds meaning" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Fluid around the heart can dampen heart sounds."}, {"id": "b", "text": "Bradycardia is the expected compensatory response."}, {"id": "c", "text": "Muffled sounds indicate hyperdynamic output."}, {"id": "d", "text": "Pulsus paradoxus is defined as a diastolic rise."}]'::jsonb, '["a"]'::jsonb, 'Correct because Muffled tones occur because pericardial fluid dampens auscultated sounds. Correlate difficult auscultation with other tamponade signs rather than dismissing technique.', 'Cardiac Tamponade - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "JVD mechanism" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "JVD mechanism" in Cardiac Tamponade?', '[{"id": "a", "text": "JVD in tamponade represents low venous pressure."}, {"id": "b", "text": "Bradycardia is the expected compensatory response."}, {"id": "c", "text": "Heart rate has no monitoring value in tamponade."}, {"id": "d", "text": "Impaired right-heart filling contributes to JVD."}]'::jsonb, '["d"]'::jsonb, 'Correct because JVD reflects impaired right-heart filling and backed-up venous pressure. Use venous congestion findings to support obstructive physiology.', 'Cardiac Tamponade - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hypotension pattern" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Hypotension pattern" in Cardiac Tamponade?', '[{"id": "a", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "b", "text": "Water-bottle silhouette confirms acute coronary occlusion."}, {"id": "c", "text": "Treat narrowing pulse pressure with falling BP as decompensation."}, {"id": "d", "text": "Hypotension is not expected in tamponade according to this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Hypotension occurs from reduced cardiac output and often presents with narrow pulse pressure. Treat narrowing pulse pressure with falling BP as decompensation.', 'Cardiac Tamponade - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pulsus paradoxus" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Pulsus paradoxus" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Pulsus paradoxus supports tamponade assessment."}, {"id": "b", "text": "Pulsus paradoxus is defined as a diastolic rise."}, {"id": "c", "text": "Electrical alternans is a benign normal variant."}, {"id": "d", "text": "Tamponade is always asymptomatic until arrest."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pulsus paradoxus is a >10 mmHg systolic BP drop during inspiration. Use this measurement to reinforce tamponade suspicion in unstable patients.', 'Cardiac Tamponade - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Compensatory tachycardia" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Compensatory tachycardia" is most accurate?', '[{"id": "a", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "b", "text": "Bradycardia is the expected compensatory response."}, {"id": "c", "text": "Tachycardia can be a compensatory response in tamponade."}, {"id": "d", "text": "High-voltage QRS is the defining tamponade pattern."}]'::jsonb, '["c"]'::jsonb, 'Correct because Tachycardia is listed as a compensatory sign in tamponade. Interpret rising heart rate with perfusion decline as compensation failure risk.', 'Cardiac Tamponade - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Perfusion decline" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Perfusion decline" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Increased urine output is expected in tamponade shock."}, {"id": "b", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "c", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "d", "text": "Prioritize perfusion rescue and definitive decompression."}]'::jsonb, '["d"]'::jsonb, 'Correct because Cool clammy skin and decreased urine output are signs of shock/perfusion compromise. Prioritize perfusion rescue and definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Respiratory/general signs" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Respiratory/general signs" in Cardiac Tamponade?', '[{"id": "a", "text": "Dysphagia cannot occur with larger effusions."}, {"id": "b", "text": "Echo has no role in tamponade diagnosis."}, {"id": "c", "text": "Orthopnea can be present in tamponade."}, {"id": "d", "text": "Normal silhouette excludes tamponade."}]'::jsonb, '["c"]'::jsonb, 'Correct because Dyspnea, orthopnea, anxiety/restlessness, and possible dysphagia are listed additional findings. Interpret escalating respiratory distress and anxiety as potential hemodynamic deterioration.', 'Cardiac Tamponade - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Electrical alternans" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Electrical alternans" in Cardiac Tamponade?', '[{"id": "a", "text": "Electrical alternans is a benign normal variant."}, {"id": "b", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "c", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}, {"id": "d", "text": "Treat electrical alternans as a red-flag trigger for immediate escalation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Electrical alternans (alternating QRS amplitude) is pathognomonic and tamponade until proven otherwise. Treat electrical alternans as a red-flag trigger for immediate escalation.', 'Cardiac Tamponade - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Other EKG clues" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Other EKG clues" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "b", "text": "High-dose vasodilators are first-line tamponade stabilizers."}, {"id": "c", "text": "Integrate EKG pattern with etiology and bedside instability."}, {"id": "d", "text": "Diuretics alone are definitive first-line emergency treatment."}]'::jsonb, '["c"]'::jsonb, 'Correct because Low-voltage QRS and sinus tachycardia are common; diffuse ST elevation can appear if pericarditis is the cause. Integrate EKG pattern with etiology and bedside instability.', 'Cardiac Tamponade - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Echo diagnosis" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Echo diagnosis" is most accurate?', '[{"id": "a", "text": "Echo can show pericardial effusion and chamber compression."}, {"id": "b", "text": "Pericardial window is contraindicated in recurrent tamponade."}, {"id": "c", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "d", "text": "Echo has no role in tamponade diagnosis."}]'::jsonb, '["a"]'::jsonb, 'Correct because Echocardiogram is the gold standard and shows effusion with chamber compression. Expedite bedside echo in unstable patients with suspected tamponade.', 'Cardiac Tamponade - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Chest X-ray clue" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Chest X-ray clue" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Water-bottle silhouette confirms acute coronary occlusion."}, {"id": "b", "text": "Use X-ray as supportive evidence, not a delay to treatment."}, {"id": "c", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "d", "text": "Pericardial fluid analysis is unnecessary after aspiration."}]'::jsonb, '["b"]'::jsonb, 'Correct because Chest X-ray may show an enlarged water-bottle cardiac silhouette. Use X-ray as supportive evidence, not a delay to treatment.', 'Cardiac Tamponade - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Pericardiocentesis emergency" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Pericardiocentesis emergency" in Cardiac Tamponade?', '[{"id": "a", "text": "Urgent provider notification and procedural preparation are priorities."}, {"id": "b", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}, {"id": "c", "text": "Pericardiocentesis should be deferred until routine clinic follow-up."}, {"id": "d", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}]'::jsonb, '["a"]'::jsonb, 'Correct because Immediate pericardiocentesis is the emergency treatment. Prepare urgently and do not delay for nonessential steps.', 'Cardiac Tamponade - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Pericardiocentesis technique" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Pericardiocentesis technique" in Cardiac Tamponade?', '[{"id": "a", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "b", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}, {"id": "c", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "d", "text": "Anticipate setup details to reduce delay during emergency decompression."}]'::jsonb, '["d"]'::jsonb, 'Correct because Patient is semi-recumbent at 45°, needle subxiphoid toward left shoulder. Anticipate setup details to reduce delay during emergency decompression.', 'Cardiac Tamponade - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Small-volume benefit" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Small-volume benefit" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Removing even 20–50 mL can significantly increase cardiac output."}, {"id": "b", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "c", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "d", "text": "Positive pressure ventilation always improves tamponade preload."}]'::jsonb, '["a"]'::jsonb, 'Correct because Removing even 20–50 mL can significantly increase cardiac output. Recognize that early partial decompression can rapidly stabilize perfusion.', 'Cardiac Tamponade - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Fluid analysis" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Fluid analysis" is most accurate?', '[{"id": "a", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "b", "text": "Tamponade increases preload by compressing the ventricles."}, {"id": "c", "text": "Routine discharge teaching is first action."}, {"id": "d", "text": "Pair emergency stabilization with etiology workup."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericardial fluid should be sent for culture, cytology, and chemistry. Pair emergency stabilization with etiology workup.', 'Cardiac Tamponade - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Supportive preload strategy" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Supportive preload strategy" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Volume rate of accumulation is irrelevant in tamponade risk."}, {"id": "b", "text": "Tamponade management avoids all IV fluid administration."}, {"id": "c", "text": "IV fluid bolus is used to maintain preload in tamponade."}, {"id": "d", "text": "All preload support is contraindicated in tamponade."}]'::jsonb, '["c"]'::jsonb, 'Correct because IV fluid bolus is used to maintain preload in tamponade. Maintain filling while arranging definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Avoidance list" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Avoidance list" in Cardiac Tamponade?', '[{"id": "a", "text": "The note says cough is a classic MI hallmark finding."}, {"id": "b", "text": "Prevent iatrogenic preload reduction in unstable tamponade."}, {"id": "c", "text": "High-dose vasodilators are first-line tamponade stabilizers."}, {"id": "d", "text": "Positive pressure ventilation always improves tamponade preload."}]'::jsonb, '["b"]'::jsonb, 'Correct because Avoid diuretics and vasodilators; avoid positive pressure ventilation when possible due to reduced venous return. Prevent iatrogenic preload reduction in unstable tamponade.', 'Cardiac Tamponade - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Surgical option" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Surgical option" in Cardiac Tamponade?', '[{"id": "a", "text": "Definitive surgical drainage may be needed after repeated episodes."}, {"id": "b", "text": "Recurrence is impossible after one aspiration according to this note."}, {"id": "c", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "d", "text": "Pericardial window is contraindicated in recurrent tamponade."}]'::jsonb, '["a"]'::jsonb, 'Correct because Pericardial window is considered for recurrent tamponade. Plan recurrence management beyond initial aspiration.', 'Cardiac Tamponade - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "NCLEX first action" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "NCLEX first action" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "b", "text": "Do not delay life-saving decompression for low-yield tasks."}, {"id": "c", "text": "Observation-only management is adequate in suspected tamponade."}, {"id": "d", "text": "Tamponade is primarily distributive shock from vasodilation."}]'::jsonb, '["b"]'::jsonb, 'Correct because First action is immediate provider notification and preparation for pericardiocentesis. Do not delay life-saving decompression for low-yield tasks.', 'Cardiac Tamponade - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Post-procedure monitoring" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Post-procedure monitoring" is most accurate?', '[{"id": "a", "text": "Muffled sounds indicate hyperdynamic output."}, {"id": "b", "text": "Only massive chronic effusions can cause tamponade."}, {"id": "c", "text": "Sustain surveillance after initial stabilization."}, {"id": "d", "text": "No monitoring is needed after successful aspiration."}]'::jsonb, '["c"]'::jsonb, 'Correct because After pericardiocentesis, monitor for re-accumulation because symptoms can return. Sustain surveillance after initial stabilization.', 'Cardiac Tamponade - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Differentiation clue" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Differentiation clue" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "The note says cough is a classic MI hallmark finding."}, {"id": "b", "text": "Tamponade/pericardial pain may worsen with coughing."}, {"id": "c", "text": "Only massive chronic effusions can cause tamponade."}, {"id": "d", "text": "Tamponade is only caused by isolated dehydration."}]'::jsonb, '["b"]'::jsonb, 'Correct because The note states tamponade chest pain worsens during expiration and coughing; cough is not typical of MI. Use distinguishing chest pain pattern and associated symptoms for differential prioritization.', 'Cardiac Tamponade - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Definition" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Definition" in Cardiac Tamponade?', '[{"id": "a", "text": "Tamponade involves pericardial fluid compressing cardiac chambers."}, {"id": "b", "text": "Hypotension is not expected in tamponade according to this note."}, {"id": "c", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "d", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}]'::jsonb, '["a"]'::jsonb, 'Correct because Cardiac tamponade is fluid accumulation in the pericardial sac that compresses the heart. Treat as an emergency because rapid deterioration and arrest can occur.', 'Cardiac Tamponade - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Hemodynamic mechanism" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Hemodynamic mechanism" in Cardiac Tamponade?', '[{"id": "a", "text": "Tamponade can produce obstructive shock physiology."}, {"id": "b", "text": "Tamponade increases preload by compressing the ventricles."}, {"id": "c", "text": "Tamponade causes are limited to congenital defects."}, {"id": "d", "text": "Radiation therapy cannot contribute to tamponade."}]'::jsonb, '["a"]'::jsonb, 'Correct because Increased intrapericardial pressure compresses all four chambers and causes obstructive shock. Recognize obstructive shock pattern when hypotension and poor perfusion progress.', 'Cardiac Tamponade - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Acute volume threshold" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Acute volume threshold" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Bradycardia is the expected compensatory response."}, {"id": "b", "text": "Only massive chronic effusions can cause tamponade."}, {"id": "c", "text": "A relatively small acute effusion can be dangerous."}, {"id": "d", "text": "Heart rate has no monitoring value in tamponade."}]'::jsonb, '["c"]'::jsonb, 'Correct because As little as 150–200 mL acutely accumulated fluid can cause tamponade. Do not underestimate small but rapidly accumulating effusions.', 'Cardiac Tamponade - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Cause profile" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Cause profile" is most accurate?', '[{"id": "a", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "b", "text": "Malignancy and post-cardiac surgery are recognized causes."}, {"id": "c", "text": "Aortic dissection is excluded as a tamponade cause."}, {"id": "d", "text": "Increased urine output is expected in tamponade shock."}]'::jsonb, '["b"]'::jsonb, 'Correct because Pericarditis is the most common cause, with trauma, post-op bleeding, malignancy, and aortic dissection also listed. Screen etiology rapidly while preparing definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Additional causes" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Additional causes" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "b", "text": "Tamponade causes are limited to congenital defects."}, {"id": "c", "text": "Hypotension is not expected in tamponade according to this note."}, {"id": "d", "text": "Iatrogenic catheter-related complications can cause tamponade."}]'::jsonb, '["d"]'::jsonb, 'Correct because Additional causes include MI free-wall rupture, iatrogenic catheterization complications, SLE, uremia, and radiation therapy. Integrate procedural and systemic risk factors into rapid triage.', 'Cardiac Tamponade - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Beck triad" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Beck triad" in Cardiac Tamponade?', '[{"id": "a", "text": "Electrical alternans is a benign normal variant."}, {"id": "b", "text": "Muffled heart sounds are part of Beck triad."}, {"id": "c", "text": "Wheezing replaces JVD in Beck triad."}, {"id": "d", "text": "Tamponade typically causes widened pulse pressure."}]'::jsonb, '["b"]'::jsonb, 'Correct because Beck triad consists of muffled heart sounds, JVD, and hypotension. Escalate immediately when triad features cluster together.', 'Cardiac Tamponade - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Muffled heart sounds meaning" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Muffled heart sounds meaning" in Cardiac Tamponade?', '[{"id": "a", "text": "A 2 mmHg inspiratory change defines pulsus paradoxus."}, {"id": "b", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "c", "text": "Auscultation findings can be subtle but clinically important."}, {"id": "d", "text": "Muffled sounds indicate hyperdynamic output."}]'::jsonb, '["c"]'::jsonb, 'Correct because Muffled tones occur because pericardial fluid dampens auscultated sounds. Correlate difficult auscultation with other tamponade signs rather than dismissing technique.', 'Cardiac Tamponade - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "JVD mechanism" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "JVD mechanism" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Backed-up venous pressure can appear as neck vein distension."}, {"id": "b", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "c", "text": "Bradycardia is the expected compensatory response."}, {"id": "d", "text": "JVD in tamponade represents low venous pressure."}]'::jsonb, '["a"]'::jsonb, 'Correct because JVD reflects impaired right-heart filling and backed-up venous pressure. Use venous congestion findings to support obstructive physiology.', 'Cardiac Tamponade - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Hypotension pattern" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Hypotension pattern" is most accurate?', '[{"id": "a", "text": "Hypotension should prompt emergency intervention readiness."}, {"id": "b", "text": "Hypotension is not expected in tamponade according to this note."}, {"id": "c", "text": "Water-bottle silhouette confirms acute coronary occlusion."}, {"id": "d", "text": "Warm dry skin is listed as hallmark obstructive shock."}]'::jsonb, '["a"]'::jsonb, 'Correct because Hypotension occurs from reduced cardiac output and often presents with narrow pulse pressure. Treat narrowing pulse pressure with falling BP as decompensation.', 'Cardiac Tamponade - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Pulsus paradoxus" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Pulsus paradoxus" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "A 2 mmHg inspiratory change defines pulsus paradoxus."}, {"id": "b", "text": "Pericardiocentesis should be deferred until routine clinic follow-up."}, {"id": "c", "text": "Diuretics alone are definitive first-line emergency treatment."}, {"id": "d", "text": "A >10 mmHg inspiratory systolic drop indicates pulsus paradoxus."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pulsus paradoxus is a >10 mmHg systolic BP drop during inspiration. Use this measurement to reinforce tamponade suspicion in unstable patients.', 'Cardiac Tamponade - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Compensatory tachycardia" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Compensatory tachycardia" in Cardiac Tamponade?', '[{"id": "a", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "b", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "c", "text": "Bradycardia is the expected compensatory response."}, {"id": "d", "text": "Trend vitals rather than evaluating heart rate in isolation."}]'::jsonb, '["d"]'::jsonb, 'Correct because Tachycardia is listed as a compensatory sign in tamponade. Interpret rising heart rate with perfusion decline as compensation failure risk.', 'Cardiac Tamponade - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Perfusion decline" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Perfusion decline" in Cardiac Tamponade?', '[{"id": "a", "text": "High-voltage QRS is the defining tamponade pattern."}, {"id": "b", "text": "Increased urine output is expected in tamponade shock."}, {"id": "c", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "d", "text": "Urine output may decrease with low cardiac output."}]'::jsonb, '["d"]'::jsonb, 'Correct because Cool clammy skin and decreased urine output are signs of shock/perfusion compromise. Prioritize perfusion rescue and definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Respiratory/general signs" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Respiratory/general signs" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Echo has no role in tamponade diagnosis."}, {"id": "b", "text": "Chest X-ray is the gold standard."}, {"id": "c", "text": "Dysphagia cannot occur with larger effusions."}, {"id": "d", "text": "Orthopnea can be present in tamponade."}]'::jsonb, '["d"]'::jsonb, 'Correct because Dyspnea, orthopnea, anxiety/restlessness, and possible dysphagia are listed additional findings. Interpret escalating respiratory distress and anxiety as potential hemodynamic deterioration.', 'Cardiac Tamponade - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Electrical alternans" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Electrical alternans" is most accurate?', '[{"id": "a", "text": "Treat electrical alternans as a red-flag trigger for immediate escalation."}, {"id": "b", "text": "Electrical alternans is a benign normal variant."}, {"id": "c", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}, {"id": "d", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}]'::jsonb, '["a"]'::jsonb, 'Correct because Electrical alternans (alternating QRS amplitude) is pathognomonic and tamponade until proven otherwise. Treat electrical alternans as a red-flag trigger for immediate escalation.', 'Cardiac Tamponade - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Other EKG clues" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Other EKG clues" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "High-voltage QRS is the defining tamponade pattern."}, {"id": "b", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "c", "text": "Needle is directed toward the right hip."}, {"id": "d", "text": "Sinus tachycardia is a common rhythm finding."}]'::jsonb, '["d"]'::jsonb, 'Correct because Low-voltage QRS and sinus tachycardia are common; diffuse ST elevation can appear if pericarditis is the cause. Integrate EKG pattern with etiology and bedside instability.', 'Cardiac Tamponade - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Echo diagnosis" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Echo diagnosis" in Cardiac Tamponade?', '[{"id": "a", "text": "Pericardial window is contraindicated in recurrent tamponade."}, {"id": "b", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "c", "text": "Echo has no role in tamponade diagnosis."}, {"id": "d", "text": "Echocardiography is the gold-standard diagnostic test."}]'::jsonb, '["d"]'::jsonb, 'Correct because Echocardiogram is the gold standard and shows effusion with chamber compression. Expedite bedside echo in unstable patients with suspected tamponade.', 'Cardiac Tamponade - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Chest X-ray clue" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Chest X-ray clue" in Cardiac Tamponade?', '[{"id": "a", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "b", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "c", "text": "Water-bottle silhouette confirms acute coronary occlusion."}, {"id": "d", "text": "Use X-ray as supportive evidence, not a delay to treatment."}]'::jsonb, '["d"]'::jsonb, 'Correct because Chest X-ray may show an enlarged water-bottle cardiac silhouette. Use X-ray as supportive evidence, not a delay to treatment.', 'Cardiac Tamponade - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pericardiocentesis emergency" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Pericardiocentesis emergency" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "b", "text": "Diuretics alone are definitive first-line emergency treatment."}, {"id": "c", "text": "Pericardiocentesis is the immediate definitive intervention."}, {"id": "d", "text": "Pericardial fluid analysis is unnecessary after aspiration."}]'::jsonb, '["c"]'::jsonb, 'Correct because Immediate pericardiocentesis is the emergency treatment. Prepare urgently and do not delay for nonessential steps.', 'Cardiac Tamponade - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Cardiac Tamponade note, which statement about "Pericardiocentesis technique" is most accurate?', 'According to the Cardiac Tamponade note, which statement about "Pericardiocentesis technique" is most accurate?', '[{"id": "a", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "b", "text": "Immediate deterioration risk is low, so urgent escalation is unnecessary."}, {"id": "c", "text": "Patient is semi-recumbent at 45°, needle subxiphoid toward left shoulder."}, {"id": "d", "text": "Preload reduction is preferred before confirming diagnosis in unstable cases."}]'::jsonb, '["c"]'::jsonb, 'Correct because Patient is semi-recumbent at 45°, needle subxiphoid toward left shoulder. Anticipate setup details to reduce delay during emergency decompression.', 'Cardiac Tamponade - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Small-volume benefit" in Cardiac Tamponade. Which statement is correct?', 'The nurse is reviewing "Small-volume benefit" in Cardiac Tamponade. Which statement is correct?', '[{"id": "a", "text": "Recurrence is impossible after one aspiration according to this note."}, {"id": "b", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "c", "text": "Clinical response should be reassessed continuously after drainage."}, {"id": "d", "text": "Tamponade improves ventricular filling and raises cardiac output."}]'::jsonb, '["c"]'::jsonb, 'Correct because Removing even 20–50 mL can significantly increase cardiac output. Recognize that early partial decompression can rapidly stabilize perfusion.', 'Cardiac Tamponade - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Fluid analysis" in Cardiac Tamponade?', 'Which clinical judgment is most accurate regarding "Fluid analysis" in Cardiac Tamponade?', '[{"id": "a", "text": "Tamponade increases preload by compressing the ventricles."}, {"id": "b", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "c", "text": "Pericardial fluid analysis is unnecessary after aspiration."}, {"id": "d", "text": "Pair emergency stabilization with etiology workup."}]'::jsonb, '["d"]'::jsonb, 'Correct because Pericardial fluid should be sent for culture, cytology, and chemistry. Pair emergency stabilization with etiology workup.', 'Cardiac Tamponade - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Supportive preload strategy" in Cardiac Tamponade?', 'In rapid prioritization, which statement is most consistent with "Supportive preload strategy" in Cardiac Tamponade?', '[{"id": "a", "text": "Tamponade management avoids all IV fluid administration."}, {"id": "b", "text": "Maintain filling while arranging definitive decompression."}, {"id": "c", "text": "Volume rate of accumulation is irrelevant in tamponade risk."}, {"id": "d", "text": "Observation-only management is adequate in suspected tamponade."}]'::jsonb, '["b"]'::jsonb, 'Correct because IV fluid bolus is used to maintain preload in tamponade. Maintain filling while arranging definitive decompression.', 'Cardiac Tamponade - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Avoidance list" in Cardiac Tamponade would the nurse recognize as correct?', 'Which conclusion about "Avoidance list" in Cardiac Tamponade would the nurse recognize as correct?', '[{"id": "a", "text": "No monitoring is needed after successful aspiration."}, {"id": "b", "text": "Aortic dissection is excluded as a tamponade cause."}, {"id": "c", "text": "Vasodilators can worsen hemodynamics by reducing preload."}, {"id": "d", "text": "High-dose vasodilators are first-line tamponade stabilizers."}]'::jsonb, '["c"]'::jsonb, 'Correct because Avoid diuretics and vasodilators; avoid positive pressure ventilation when possible due to reduced venous return. Prevent iatrogenic preload reduction in unstable tamponade.', 'Cardiac Tamponade - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Definition" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Definition" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "b", "text": "Cardiac output falls when ventricular filling is impaired."}, {"id": "c", "text": "Tamponade involves pericardial fluid compressing cardiac chambers."}, {"id": "d", "text": "Untreated tamponade can be rapidly fatal."}, {"id": "e", "text": "Tamponade is a benign condition that can always wait for routine follow-up."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Cardiac tamponade is fluid accumulation in the pericardial sac that compresses the heart.', 'Cardiac Tamponade - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Hemodynamic mechanism"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Hemodynamic mechanism"? (Select all that apply)', '[{"id": "a", "text": "Tamponade increases preload by compressing the ventricles."}, {"id": "b", "text": "Tamponade is primarily distributive shock from vasodilation."}, {"id": "c", "text": "Rising intrapericardial pressure limits chamber filling."}, {"id": "d", "text": "Tamponade can produce obstructive shock physiology."}, {"id": "e", "text": "Reduced preload leads to reduced cardiac output."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Increased intrapericardial pressure compresses all four chambers and causes obstructive shock.', 'Cardiac Tamponade - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Acute volume threshold" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Acute volume threshold" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Volume rate of accumulation is irrelevant in tamponade risk."}, {"id": "b", "text": "Clinical deterioration depends on accumulation speed, not only total volume."}, {"id": "c", "text": "Only massive chronic effusions can cause tamponade."}, {"id": "d", "text": "Rapid accumulation allows less compensation time."}, {"id": "e", "text": "A relatively small acute effusion can be dangerous."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: As little as 150–200 mL acutely accumulated fluid can cause tamponade.', 'Cardiac Tamponade - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Cause profile" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Cause profile" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Aortic dissection is excluded as a tamponade cause."}, {"id": "b", "text": "Pericarditis is listed as the most common cause."}, {"id": "c", "text": "Tamponade is only caused by isolated dehydration."}, {"id": "d", "text": "Malignancy and post-cardiac surgery are recognized causes."}, {"id": "e", "text": "Penetrating or blunt trauma can precipitate tamponade."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis is the most common cause, with trauma, post-op bleeding, malignancy, and aortic dissection also listed.', 'Cardiac Tamponade - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Additional causes" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Additional causes" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Iatrogenic catheter-related complications can cause tamponade."}, {"id": "b", "text": "Autoimmune disease and uremia are included causes."}, {"id": "c", "text": "Radiation therapy cannot contribute to tamponade."}, {"id": "d", "text": "MI free-wall rupture is listed as a cause."}, {"id": "e", "text": "Tamponade causes are limited to congenital defects."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Additional causes include MI free-wall rupture, iatrogenic catheterization complications, SLE, uremia, and radiation therapy.', 'Cardiac Tamponade - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Beck triad" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Beck triad" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Wheezing replaces JVD in Beck triad."}, {"id": "b", "text": "Hypotension is part of Beck triad."}, {"id": "c", "text": "JVD is part of Beck triad."}, {"id": "d", "text": "Hypertension is part of Beck triad."}, {"id": "e", "text": "Muffled heart sounds are part of Beck triad."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Beck triad consists of muffled heart sounds, JVD, and hypotension.', 'Cardiac Tamponade - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Muffled heart sounds meaning"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Muffled heart sounds meaning"? (Select all that apply)', '[{"id": "a", "text": "Muffled sounds indicate hyperdynamic output."}, {"id": "b", "text": "Auscultation findings can be subtle but clinically important."}, {"id": "c", "text": "Fluid around the heart can dampen heart sounds."}, {"id": "d", "text": "Muffled tones should be interpreted alongside hypotension and JVD."}, {"id": "e", "text": "Muffled tones rule out tamponade."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Muffled tones occur because pericardial fluid dampens auscultated sounds.', 'Cardiac Tamponade - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "JVD mechanism" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "JVD mechanism" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "JVD is unrelated to right-heart filling."}, {"id": "b", "text": "JVD is a high-yield bedside tamponade clue."}, {"id": "c", "text": "JVD in tamponade represents low venous pressure."}, {"id": "d", "text": "Backed-up venous pressure can appear as neck vein distension."}, {"id": "e", "text": "Impaired right-heart filling contributes to JVD."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: JVD reflects impaired right-heart filling and backed-up venous pressure.', 'Cardiac Tamponade - NCLEX', true, 58, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hypotension pattern" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Hypotension pattern" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Reduced cardiac output contributes to hypotension."}, {"id": "b", "text": "Narrow pulse pressure can occur in tamponade."}, {"id": "c", "text": "Tamponade typically causes widened pulse pressure."}, {"id": "d", "text": "Hypotension is not expected in tamponade according to this note."}, {"id": "e", "text": "Hypotension should prompt emergency intervention readiness."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Hypotension occurs from reduced cardiac output and often presents with narrow pulse pressure.', 'Cardiac Tamponade - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pulsus paradoxus" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Pulsus paradoxus" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "A >10 mmHg inspiratory systolic drop indicates pulsus paradoxus."}, {"id": "b", "text": "Pulsus paradoxus supports tamponade assessment."}, {"id": "c", "text": "Inspiratory BP variation is specifically emphasized."}, {"id": "d", "text": "Pulsus paradoxus is defined as a diastolic rise."}, {"id": "e", "text": "A 2 mmHg inspiratory change defines pulsus paradoxus."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Pulsus paradoxus is a >10 mmHg systolic BP drop during inspiration.', 'Cardiac Tamponade - NCLEX', true, 60, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Compensatory tachycardia" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Compensatory tachycardia" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Trend vitals rather than evaluating heart rate in isolation."}, {"id": "b", "text": "Heart rate has no monitoring value in tamponade."}, {"id": "c", "text": "Compensation may coexist with hypotension as condition worsens."}, {"id": "d", "text": "Bradycardia is the expected compensatory response."}, {"id": "e", "text": "Tachycardia can be a compensatory response in tamponade."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Tachycardia is listed as a compensatory sign in tamponade.', 'Cardiac Tamponade - NCLEX', true, 61, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Perfusion decline"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Perfusion decline"? (Select all that apply)', '[{"id": "a", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "b", "text": "Increased urine output is expected in tamponade shock."}, {"id": "c", "text": "Cool clammy skin can indicate shock in tamponade."}, {"id": "d", "text": "Perfusion signs should be trended urgently."}, {"id": "e", "text": "Urine output may decrease with low cardiac output."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cool clammy skin and decreased urine output are signs of shock/perfusion compromise.', 'Cardiac Tamponade - NCLEX', true, 62, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Respiratory/general signs" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Respiratory/general signs" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Tamponade is always asymptomatic until arrest."}, {"id": "b", "text": "Dysphagia cannot occur with larger effusions."}, {"id": "c", "text": "Anxiety and restlessness are compatible with acute instability."}, {"id": "d", "text": "Dyspnea may occur with tamponade."}, {"id": "e", "text": "Orthopnea can be present in tamponade."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Dyspnea, orthopnea, anxiety/restlessness, and possible dysphagia are listed additional findings.', 'Cardiac Tamponade - NCLEX', true, 63, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Electrical alternans" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Electrical alternans" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Electrical alternans is a benign normal variant."}, {"id": "b", "text": "Alternans should trigger urgent provider notification and prep for intervention."}, {"id": "c", "text": "Electrical alternans is beat-to-beat QRS amplitude variation."}, {"id": "d", "text": "Alternans excludes pericardial fluid."}, {"id": "e", "text": "Electrical alternans strongly supports tamponade."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Electrical alternans (alternating QRS amplitude) is pathognomonic and tamponade until proven otherwise.', 'Cardiac Tamponade - NCLEX', true, 64, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Other EKG clues" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Other EKG clues" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Low-voltage QRS can appear in tamponade."}, {"id": "b", "text": "High-voltage QRS is the defining tamponade pattern."}, {"id": "c", "text": "Diffuse ST elevation may occur when pericarditis underlies tamponade."}, {"id": "d", "text": "Tamponade cannot coexist with pericarditis EKG changes."}, {"id": "e", "text": "Sinus tachycardia is a common rhythm finding."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Low-voltage QRS and sinus tachycardia are common; diffuse ST elevation can appear if pericarditis is the cause.', 'Cardiac Tamponade - NCLEX', true, 65, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Echo diagnosis" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Echo diagnosis" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Chest X-ray is the gold standard."}, {"id": "b", "text": "Echo has no role in tamponade diagnosis."}, {"id": "c", "text": "Echocardiography is the gold-standard diagnostic test."}, {"id": "d", "text": "Echo can show pericardial effusion and chamber compression."}, {"id": "e", "text": "Echo findings guide urgent decompression decisions."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Echocardiogram is the gold standard and shows effusion with chamber compression.', 'Cardiac Tamponade - NCLEX', true, 66, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Chest X-ray clue"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Chest X-ray clue"? (Select all that apply)', '[{"id": "a", "text": "Imaging should be integrated with hemodynamics and bedside findings."}, {"id": "b", "text": "X-ray is supportive but not the definitive emergent test."}, {"id": "c", "text": "A water-bottle silhouette can support tamponade suspicion."}, {"id": "d", "text": "Normal silhouette excludes tamponade."}, {"id": "e", "text": "Water-bottle silhouette confirms acute coronary occlusion."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Chest X-ray may show an enlarged water-bottle cardiac silhouette.', 'Cardiac Tamponade - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Pericardiocentesis emergency" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Pericardiocentesis emergency" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Pericardiocentesis should be deferred until routine clinic follow-up."}, {"id": "b", "text": "Rapid decompression can be lifesaving in tamponade."}, {"id": "c", "text": "Pericardiocentesis is the immediate definitive intervention."}, {"id": "d", "text": "Urgent provider notification and procedural preparation are priorities."}, {"id": "e", "text": "Diuretics alone are definitive first-line emergency treatment."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Immediate pericardiocentesis is the emergency treatment.', 'Cardiac Tamponade - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Pericardiocentesis technique" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Pericardiocentesis technique" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Subxiphoid entry directed toward the left shoulder is described."}, {"id": "b", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "c", "text": "Procedure setup should be rapid and organized."}, {"id": "d", "text": "Semi-recumbent positioning at about 45° is listed."}, {"id": "e", "text": "Needle is directed toward the right hip."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Patient is semi-recumbent at 45°, needle subxiphoid toward left shoulder.', 'Cardiac Tamponade - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Small-volume benefit" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Small-volume benefit" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Cardiac output may rise after limited fluid removal."}, {"id": "b", "text": "Drainage has no immediate effect on output."}, {"id": "c", "text": "At least 1 liter must be removed before hemodynamics improve."}, {"id": "d", "text": "Clinical response should be reassessed continuously after drainage."}, {"id": "e", "text": "Small-volume drainage can produce meaningful hemodynamic improvement."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Removing even 20–50 mL can significantly increase cardiac output.', 'Cardiac Tamponade - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Fluid analysis" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Fluid analysis" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Culture is part of fluid analysis."}, {"id": "b", "text": "Pericardial fluid analysis is unnecessary after aspiration."}, {"id": "c", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "d", "text": "Cytology is part of fluid analysis."}, {"id": "e", "text": "Chemistry testing is part of fluid analysis."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericardial fluid should be sent for culture, cytology, and chemistry.', 'Cardiac Tamponade - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Supportive preload strategy"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Supportive preload strategy"? (Select all that apply)', '[{"id": "a", "text": "Tamponade management avoids all IV fluid administration."}, {"id": "b", "text": "IV fluids may support preload in tamponade."}, {"id": "c", "text": "Preload support can temporarily improve hemodynamics."}, {"id": "d", "text": "Supportive therapy does not replace urgent pericardiocentesis."}, {"id": "e", "text": "All preload support is contraindicated in tamponade."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: IV fluid bolus is used to maintain preload in tamponade.', 'Cardiac Tamponade - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Avoidance list" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Avoidance list" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Vasodilators can worsen hemodynamics by reducing preload."}, {"id": "b", "text": "Diuretics can worsen preload in tamponade."}, {"id": "c", "text": "High-dose vasodilators are first-line tamponade stabilizers."}, {"id": "d", "text": "Positive pressure ventilation may reduce venous return and should be avoided if possible."}, {"id": "e", "text": "Positive pressure ventilation always improves tamponade preload."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Avoid diuretics and vasodilators; avoid positive pressure ventilation when possible due to reduced venous return.', 'Cardiac Tamponade - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Surgical option" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Surgical option" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Recurrence is impossible after one aspiration according to this note."}, {"id": "b", "text": "Pericardial window is listed for recurrent tamponade."}, {"id": "c", "text": "Pericardial window is contraindicated in recurrent tamponade."}, {"id": "d", "text": "Definitive surgical drainage may be needed after repeated episodes."}, {"id": "e", "text": "Recurrence risk requires ongoing follow-up planning."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pericardial window is considered for recurrent tamponade.', 'Cardiac Tamponade - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "NCLEX first action" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "NCLEX first action" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Delay can lead to arrest within minutes."}, {"id": "b", "text": "Routine discharge teaching is first action."}, {"id": "c", "text": "Observation-only management is adequate in suspected tamponade."}, {"id": "d", "text": "Preparation for pericardiocentesis is urgent."}, {"id": "e", "text": "Immediate provider notification is prioritized."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: First action is immediate provider notification and preparation for pericardiocentesis.', 'Cardiac Tamponade - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Post-procedure monitoring" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Post-procedure monitoring" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Recurrence is not possible post-procedure."}, {"id": "b", "text": "Symptoms can recur due to fluid re-accumulation."}, {"id": "c", "text": "Post-procedure monitoring is essential."}, {"id": "d", "text": "No monitoring is needed after successful aspiration."}, {"id": "e", "text": "Reassessment should include recurring hypotension/JVD/muffled tones signs."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: After pericardiocentesis, monitor for re-accumulation because symptoms can return.', 'Cardiac Tamponade - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Differentiation clue"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Differentiation clue"? (Select all that apply)', '[{"id": "a", "text": "Differential reasoning should incorporate associated respiratory features."}, {"id": "b", "text": "The note says cough is a classic MI hallmark finding."}, {"id": "c", "text": "The note contrasts this pattern with typical MI presentation."}, {"id": "d", "text": "Tamponade/pericardial pain may worsen with coughing."}, {"id": "e", "text": "Tamponade pain is unrelated to breathing/cough."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: The note states tamponade chest pain worsens during expiration and coughing; cough is not typical of MI.', 'Cardiac Tamponade - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Definition" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Definition" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Tamponade improves ventricular filling and raises cardiac output."}, {"id": "b", "text": "Tamponade involves pericardial fluid compressing cardiac chambers."}, {"id": "c", "text": "Untreated tamponade can be rapidly fatal."}, {"id": "d", "text": "Tamponade is a benign condition that can always wait for routine follow-up."}, {"id": "e", "text": "Cardiac output falls when ventricular filling is impaired."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac tamponade is fluid accumulation in the pericardial sac that compresses the heart.', 'Cardiac Tamponade - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Hemodynamic mechanism" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Hemodynamic mechanism" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Reduced preload leads to reduced cardiac output."}, {"id": "b", "text": "Rising intrapericardial pressure limits chamber filling."}, {"id": "c", "text": "Tamponade is primarily distributive shock from vasodilation."}, {"id": "d", "text": "Tamponade can produce obstructive shock physiology."}, {"id": "e", "text": "Tamponade increases preload by compressing the ventricles."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Increased intrapericardial pressure compresses all four chambers and causes obstructive shock.', 'Cardiac Tamponade - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Acute volume threshold" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Acute volume threshold" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Rapid accumulation allows less compensation time."}, {"id": "b", "text": "A relatively small acute effusion can be dangerous."}, {"id": "c", "text": "Clinical deterioration depends on accumulation speed, not only total volume."}, {"id": "d", "text": "Volume rate of accumulation is irrelevant in tamponade risk."}, {"id": "e", "text": "Only massive chronic effusions can cause tamponade."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: As little as 150–200 mL acutely accumulated fluid can cause tamponade.', 'Cardiac Tamponade - NCLEX', true, 80, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Cause profile" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Cause profile" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Malignancy and post-cardiac surgery are recognized causes."}, {"id": "b", "text": "Aortic dissection is excluded as a tamponade cause."}, {"id": "c", "text": "Penetrating or blunt trauma can precipitate tamponade."}, {"id": "d", "text": "Pericarditis is listed as the most common cause."}, {"id": "e", "text": "Tamponade is only caused by isolated dehydration."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericarditis is the most common cause, with trauma, post-op bleeding, malignancy, and aortic dissection also listed.', 'Cardiac Tamponade - NCLEX', true, 81, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Additional causes"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Additional causes"? (Select all that apply)', '[{"id": "a", "text": "Iatrogenic catheter-related complications can cause tamponade."}, {"id": "b", "text": "Autoimmune disease and uremia are included causes."}, {"id": "c", "text": "Tamponade causes are limited to congenital defects."}, {"id": "d", "text": "MI free-wall rupture is listed as a cause."}, {"id": "e", "text": "Radiation therapy cannot contribute to tamponade."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Additional causes include MI free-wall rupture, iatrogenic catheterization complications, SLE, uremia, and radiation therapy.', 'Cardiac Tamponade - NCLEX', true, 82, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Beck triad" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Beck triad" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Hypotension is part of Beck triad."}, {"id": "b", "text": "Wheezing replaces JVD in Beck triad."}, {"id": "c", "text": "Hypertension is part of Beck triad."}, {"id": "d", "text": "Muffled heart sounds are part of Beck triad."}, {"id": "e", "text": "JVD is part of Beck triad."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Beck triad consists of muffled heart sounds, JVD, and hypotension.', 'Cardiac Tamponade - NCLEX', true, 83, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Muffled heart sounds meaning" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Muffled heart sounds meaning" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Muffled tones rule out tamponade."}, {"id": "b", "text": "Fluid around the heart can dampen heart sounds."}, {"id": "c", "text": "Muffled sounds indicate hyperdynamic output."}, {"id": "d", "text": "Auscultation findings can be subtle but clinically important."}, {"id": "e", "text": "Muffled tones should be interpreted alongside hypotension and JVD."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Muffled tones occur because pericardial fluid dampens auscultated sounds.', 'Cardiac Tamponade - NCLEX', true, 84, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "JVD mechanism" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "JVD mechanism" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "JVD is a high-yield bedside tamponade clue."}, {"id": "b", "text": "Backed-up venous pressure can appear as neck vein distension."}, {"id": "c", "text": "JVD is unrelated to right-heart filling."}, {"id": "d", "text": "JVD in tamponade represents low venous pressure."}, {"id": "e", "text": "Impaired right-heart filling contributes to JVD."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: JVD reflects impaired right-heart filling and backed-up venous pressure.', 'Cardiac Tamponade - NCLEX', true, 85, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Hypotension pattern" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Hypotension pattern" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Hypotension is not expected in tamponade according to this note."}, {"id": "b", "text": "Reduced cardiac output contributes to hypotension."}, {"id": "c", "text": "Narrow pulse pressure can occur in tamponade."}, {"id": "d", "text": "Hypotension should prompt emergency intervention readiness."}, {"id": "e", "text": "Tamponade typically causes widened pulse pressure."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Hypotension occurs from reduced cardiac output and often presents with narrow pulse pressure.', 'Cardiac Tamponade - NCLEX', true, 86, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Pulsus paradoxus"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Pulsus paradoxus"? (Select all that apply)', '[{"id": "a", "text": "Pulsus paradoxus supports tamponade assessment."}, {"id": "b", "text": "A 2 mmHg inspiratory change defines pulsus paradoxus."}, {"id": "c", "text": "Pulsus paradoxus is defined as a diastolic rise."}, {"id": "d", "text": "A >10 mmHg inspiratory systolic drop indicates pulsus paradoxus."}, {"id": "e", "text": "Inspiratory BP variation is specifically emphasized."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Pulsus paradoxus is a >10 mmHg systolic BP drop during inspiration.', 'Cardiac Tamponade - NCLEX', true, 87, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Compensatory tachycardia" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Compensatory tachycardia" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Compensation may coexist with hypotension as condition worsens."}, {"id": "b", "text": "Trend vitals rather than evaluating heart rate in isolation."}, {"id": "c", "text": "Tachycardia can be a compensatory response in tamponade."}, {"id": "d", "text": "Bradycardia is the expected compensatory response."}, {"id": "e", "text": "Heart rate has no monitoring value in tamponade."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Tachycardia is listed as a compensatory sign in tamponade.', 'Cardiac Tamponade - NCLEX', true, 88, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Perfusion decline" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Perfusion decline" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Urine output may decrease with low cardiac output."}, {"id": "b", "text": "Perfusion signs should be trended urgently."}, {"id": "c", "text": "Increased urine output is expected in tamponade shock."}, {"id": "d", "text": "Warm dry skin is listed as hallmark obstructive shock."}, {"id": "e", "text": "Cool clammy skin can indicate shock in tamponade."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Cool clammy skin and decreased urine output are signs of shock/perfusion compromise.', 'Cardiac Tamponade - NCLEX', true, 89, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Respiratory/general signs" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Respiratory/general signs" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Orthopnea can be present in tamponade."}, {"id": "b", "text": "Dyspnea may occur with tamponade."}, {"id": "c", "text": "Tamponade is always asymptomatic until arrest."}, {"id": "d", "text": "Dysphagia cannot occur with larger effusions."}, {"id": "e", "text": "Anxiety and restlessness are compatible with acute instability."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Dyspnea, orthopnea, anxiety/restlessness, and possible dysphagia are listed additional findings.', 'Cardiac Tamponade - NCLEX', true, 90, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Electrical alternans" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Electrical alternans" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Alternans excludes pericardial fluid."}, {"id": "b", "text": "Alternans should trigger urgent provider notification and prep for intervention."}, {"id": "c", "text": "Electrical alternans strongly supports tamponade."}, {"id": "d", "text": "Electrical alternans is beat-to-beat QRS amplitude variation."}, {"id": "e", "text": "Electrical alternans is a benign normal variant."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Electrical alternans (alternating QRS amplitude) is pathognomonic and tamponade until proven otherwise.', 'Cardiac Tamponade - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Other EKG clues"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Other EKG clues"? (Select all that apply)', '[{"id": "a", "text": "Diffuse ST elevation may occur when pericarditis underlies tamponade."}, {"id": "b", "text": "High-voltage QRS is the defining tamponade pattern."}, {"id": "c", "text": "Low-voltage QRS can appear in tamponade."}, {"id": "d", "text": "Sinus tachycardia is a common rhythm finding."}, {"id": "e", "text": "Tamponade cannot coexist with pericarditis EKG changes."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Low-voltage QRS and sinus tachycardia are common; diffuse ST elevation can appear if pericarditis is the cause.', 'Cardiac Tamponade - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Echo diagnosis" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Echo diagnosis" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Echo has no role in tamponade diagnosis."}, {"id": "b", "text": "Chest X-ray is the gold standard."}, {"id": "c", "text": "Echocardiography is the gold-standard diagnostic test."}, {"id": "d", "text": "Echo can show pericardial effusion and chamber compression."}, {"id": "e", "text": "Echo findings guide urgent decompression decisions."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Echocardiogram is the gold standard and shows effusion with chamber compression.', 'Cardiac Tamponade - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Chest X-ray clue" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Chest X-ray clue" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Imaging should be integrated with hemodynamics and bedside findings."}, {"id": "b", "text": "Water-bottle silhouette confirms acute coronary occlusion."}, {"id": "c", "text": "X-ray is supportive but not the definitive emergent test."}, {"id": "d", "text": "A water-bottle silhouette can support tamponade suspicion."}, {"id": "e", "text": "Normal silhouette excludes tamponade."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Chest X-ray may show an enlarged water-bottle cardiac silhouette.', 'Cardiac Tamponade - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pericardiocentesis emergency" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Pericardiocentesis emergency" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Urgent provider notification and procedural preparation are priorities."}, {"id": "b", "text": "Rapid decompression can be lifesaving in tamponade."}, {"id": "c", "text": "Pericardiocentesis should be deferred until routine clinic follow-up."}, {"id": "d", "text": "Pericardiocentesis is the immediate definitive intervention."}, {"id": "e", "text": "Diuretics alone are definitive first-line emergency treatment."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Immediate pericardiocentesis is the emergency treatment.', 'Cardiac Tamponade - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Pericardiocentesis technique" in Cardiac Tamponade are correct? (Select all that apply)', 'Which statements about "Pericardiocentesis technique" in Cardiac Tamponade are correct? (Select all that apply)', '[{"id": "a", "text": "Needle is directed toward the right hip."}, {"id": "b", "text": "Procedure setup should be rapid and organized."}, {"id": "c", "text": "Prone positioning is preferred for tamponade aspiration."}, {"id": "d", "text": "Semi-recumbent positioning at about 45° is listed."}, {"id": "e", "text": "Subxiphoid entry directed toward the left shoulder is described."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Patient is semi-recumbent at 45°, needle subxiphoid toward left shoulder.', 'Cardiac Tamponade - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Cardiac Tamponade, which findings or actions relate to "Small-volume benefit"? (Select all that apply)', 'For Cardiac Tamponade, which findings or actions relate to "Small-volume benefit"? (Select all that apply)', '[{"id": "a", "text": "Drainage has no immediate effect on output."}, {"id": "b", "text": "Clinical response should be reassessed continuously after drainage."}, {"id": "c", "text": "Cardiac output may rise after limited fluid removal."}, {"id": "d", "text": "Small-volume drainage can produce meaningful hemodynamic improvement."}, {"id": "e", "text": "At least 1 liter must be removed before hemodynamics improve."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Removing even 20–50 mL can significantly increase cardiac output.', 'Cardiac Tamponade - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Fluid analysis" in Cardiac Tamponade? (Select all that apply)', 'The nurse is planning care. Which items apply to "Fluid analysis" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Culture is part of fluid analysis."}, {"id": "b", "text": "Cytology is part of fluid analysis."}, {"id": "c", "text": "Only glucose is sent, with no culture/cytology/chemistry."}, {"id": "d", "text": "Chemistry testing is part of fluid analysis."}, {"id": "e", "text": "Pericardial fluid analysis is unnecessary after aspiration."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Pericardial fluid should be sent for culture, cytology, and chemistry.', 'Cardiac Tamponade - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Supportive preload strategy" in Cardiac Tamponade? (Select all that apply)', 'Which of the following are consistent with "Supportive preload strategy" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "IV fluids may support preload in tamponade."}, {"id": "b", "text": "Tamponade management avoids all IV fluid administration."}, {"id": "c", "text": "All preload support is contraindicated in tamponade."}, {"id": "d", "text": "Supportive therapy does not replace urgent pericardiocentesis."}, {"id": "e", "text": "Preload support can temporarily improve hemodynamics."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: IV fluid bolus is used to maintain preload in tamponade.', 'Cardiac Tamponade - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Avoidance list" in Cardiac Tamponade? (Select all that apply)', 'During reassessment, which observations align with "Avoidance list" in Cardiac Tamponade? (Select all that apply)', '[{"id": "a", "text": "Diuretics can worsen preload in tamponade."}, {"id": "b", "text": "High-dose vasodilators are first-line tamponade stabilizers."}, {"id": "c", "text": "Vasodilators can worsen hemodynamics by reducing preload."}, {"id": "d", "text": "Positive pressure ventilation may reduce venous return and should be avoided if possible."}, {"id": "e", "text": "Positive pressure ventilation always improves tamponade preload."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Avoid diuretics and vasodilators; avoid positive pressure ventilation when possible due to reduced venous return.', 'Cardiac Tamponade - NCLEX', true, 100, 1, true);
